sys_script_include.script:
var CreateSaaSIntegrationTasks = Class.create();
CreateSaaSIntegrationTasks.prototype = {
    initialize: function () {},

    createSaaSTasks: function () {
        var sysPropValue = gs.getProperty("custom_walk_saas_integration");

        if (!sysPropValue) {
            gs.info("❌ System Property 'custom_walk_saas_integration' not found.");
            return "System Property not found.";
        }

        var taskInfo;
        try {
            taskInfo = JSON.parse(sysPropValue);
        } catch (e) {
            gs.error("❌ Error parsing JSON from sys_property: " + e);
            return "Error parsing system property.";
        }

        var task = new GlideRecord('samp_sp_vb_task'); // ✅ Ensure this is the correct task table
        var found = false;

        for (var i = 0; i < taskInfo.length; i++) {
            var saasKey = Object.keys(taskInfo[i])[0];

            task.initialize();
            task.short_description = taskInfo[i][saasKey].short_description.trim();
            task.description = taskInfo[i][saasKey].description;
            task.work_notes = taskInfo[i][saasKey].instruction;
            task.state = "1"; // Open
            task.insert();

            gs.info("✅ Task created in samp_sp_vb_task for SaaS Integration: " + saasKey);
            found = true;
        }

        return found ? "✅ SaaS Integration Tasks created successfully." : "❌ No SaaS integrations found.";
    },

    type: 'CreateSaaSIntegrationTasks'
};
